-- v992: контент курса «Адаптация» — День 1 · Принципы и оргсхема. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000001$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 20, $sd$День 1 · Принципы и оргсхема$sd$, $sd$Кто мы, как мы работаем друг с другом и с клиентами, где ты на схеме компании, какие инструменты нужно настроить и каких ошибок избежать.$sd$, $sd${"title":"Зачёт дня 1","tasks":["Устно объясняешь миссию компании «как клиенту» — простыми словами, без терминов","Микро-ролёвка: первые 10 секунд приветствия по телефону — тон, уверенность, представление","Рисуешь по памяти поток клиента по оргсхеме: 4 → 5 → 6 → 10/11 → 12 → 13","Называешь свой ЦКП и ЦКП двух соседних отделов; говоришь, в какой отдел передаёшь клиента после оплаты","Всё ПО из чек-листа установлено, доступы получены, NDA подписан","Wazzup установлен на телефон и ПК, вход в АТС выполнен, сделан тестовый звонок из карточки amoCRM — запись появилась в сделке","Написал тестовое сообщение клиенту по регламенту коммуникации: на Вы, по имени, со сроком ответа"],"result":"Уверенное понимание культуры и своего места в компании."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000101$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 10, $sd$Принципы работы в команде$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Что в принципах команды противопоставлено харизме?","options":["Опыт","Системность","Скорость","Удача"],"correct":1},{"q":"Как команда относится к ошибкам?","options":["Фиксирует штраф","Разбирает, не обвиняет","Замалчивает","Передаёт РОПу"],"correct":1},{"q":"Что значит «не уходить в туман»?","options":["Не брать отпуск","Если что-то не так — сказать и предложить решение","Не звонить после 18:00","Не писать в общий чат"],"correct":1},{"q":"Чья зона ответственности — новичок?","options":["Только HR","Только наставника","Всей команды","Самого новичка"],"correct":2},{"q":"Как формулируется ответственность?","options":["Делаю, когда есть время","Делаю, как обещал","Делаю, если попросят","Делаю в конце месяца"],"correct":1}]$sd$::jsonb, $sd$<p>Десять правил, по которым живёт отдел. Это не лозунги — по ним разбирают ошибки и принимают решения о грейде.</p>
<ol class="rules">
<li><b>Каждый новичок — зона ответственности команды.</b> Сильная адаптация = сильная команда.</li>
<li><b>Говорим открыто</b>, без подтекста и манипуляций.</li>
<li><b>Ошибки — точки роста.</b> Разбираем, не обвиняем.</li>
<li><b>Поддержка в сложных кейсах — норма</b>, а не героизм.</li>
<li><b>Ответственность</b> — не «делаю, когда есть время», а «делаю, как обещал».</li>
<li><b>Системность важнее харизмы.</b> Результаты рождаются из процессов.</li>
<li><b>Не уходим «в туман».</b> Если что-то не так — говорим и предлагаем решение.</li>
<li><b>Рост одного — вклад в рост команды.</b> Делимся, обучаем, развиваем.</li>
<li><b>Коммуникация</b> — не хаос в мессенджерах, а понятный ритм общения и отчётности.</li>
<li><b>Честные правила игры.</b> Договорились — выполняем. Всегда.</li>
</ol>
<div class="callout">Как это применять к себе: сначала ищи ответ в регламентах и в этой школе, потом спрашивай коллег. Вопросы, на которые можно было найти ответ самому, отвлекают команду — и учитываются в KPI.</div>$sd$, $sd$[{"t":"Принципы работы в команде","u":"https://docs.google.com/document/d/1NZFii3EeL2qbGudRBxDSsMSawrOi4TPzU6J38HnVsfg/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000102$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 20, $sd$Принципы работы с клиентами$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"С чего начинается разговор с клиентом?","options":["С презентации продукта","С понимания его задачи","С цены","С кейса Nestle"],"correct":1},{"q":"Клиент говорит «дорого». Что делаем по принципам?","options":["Даём скидку","Объясняем выгоды и окупаемость","Предлагаем подумать","Передаём РОПу"],"correct":1},{"q":"Клиент «завис». Что это для нас?","options":["Повод закрыть сделку","Сигнал проявить инициативу","Норма, ждём","Ошибка маркетинга"],"correct":1},{"q":"Индивидуальный подход — это…","options":["Гибкость в цене","Точность в решении задачи","Личные встречи","Скидка за объём"],"correct":1},{"q":"Что такое продажа для нас?","options":["Реализация IT-продукта","Помощь в автоматизации","Выполнение плана","Закрытие возражений"],"correct":1}]$sd$::jsonb, $sd$<ol class="rules">
<li><b>Начинаем с понимания задачи клиента</b>, а не с презентации продукта.</li>
<li><b>Каждый контакт</b> демонстрирует экспертность и приносит ценность.</li>
<li><b>Не торгуемся скидками</b> — объясняем выгоды и окупаемость.</li>
<li><b>Клиент «завис» — это сигнал:</b> проявляем инициативу, помогаем принять решение.</li>
<li><b>КП, обещания, созвоны — точно в срок.</b></li>
<li><b>Индивидуальный подход</b> — не гибкость в цене, а точность в решении задачи.</li>
<li><b>Быстрые и понятные форматы</b> коммуникации, чтобы не терять контакт.</li>
<li><b>Работаем на доверие</b> и долгосрочное сотрудничество, а не на разовую сделку.</li>
<li><b>Даже если клиент не прав</b> — находим путь, чтобы он остался доволен.</li>
<li><b>Продажа — это помощь в автоматизации</b>, а не реализация IT-продукта.</li>
</ol>
<h4>Как это звучит в работе</h4>
<ul>
<li>Клиент говорит «дорого» → не скидка, а расчёт окупаемости на его цифрах (день 4).</li>
<li>Клиент молчит неделю → не ждём, а делаем следующее касание из цепочки (день 5).</li>
<li>Обещал перезвонить в четверг → перезваниваешь в четверг. Что бывает за просроченные обещания — в чек-листе CRM (день 2).</li>
</ul>$sd$, $sd$[{"t":"Принципы работы с клиентами","u":"https://docs.google.com/document/d/1CzpEV_huMBQ8r7HEMfJ_fs9ukot3JzJE_33MqU7UQiI/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000103$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 30, $sd$Оргсхема: где ты на карте компании$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"В каком департаменте и отделе находится секция Sales Doctor?","options":["1 HR → отдел 2","2 Коммерческий → отдел 6 «Отдел продаж»","4 Технический → отдел 10","5 Квалификации → отдел 13"],"correct":1},{"q":"ЦКП секции Sales Doctor — это…","options":["База клиентов с актуальными данными","Доход от продаж Sales Doctor","Довольный клиент","Количество демо"],"correct":1},{"q":"Какой отдел передаёт тебе клиента, который понял ценность и хочет купить?","options":["4 Продвижение","5 Понимание","10 Ведение","12 Интеграция"],"correct":1},{"q":"Куда уходит клиент категории A после оплаты?","options":["Отдел 11","Отдел 10 (key account)","Отдел 13","Остаётся у менеджера"],"correct":1},{"q":"ЦКП коммерческого департамента:","options":["План продаж выполнен","Доход компании больше, чем расходы","Ноль просрочек","Рост базы"],"correct":1}]$sd$::jsonb, $sd$<p>Организующая схема Sales Doctor Solutions (v.6 от 06.06.2025): 7 департаментов, 21 отдел, у каждого отдела и секции свой <b>ЦКП — ценный конечный продукт</b>. То, ради чего отдел существует.</p>
<h4>Семь департаментов</h4>
<ul>
<li>7 Административный · 1 HR · <b>2 Коммерческий</b> · 3 Финансовый · 4 Технический · 5 Квалификации · 6 PR.</li>
<li>ЦКП коммерческого департамента: <b>«доход компании больше, чем расходы»</b>.</li>
</ul>
<h4>Твоё место</h4>
<p>Департамент 2 «Коммерческий» → отдел 6 «Отдел продаж» → секция Sales Doctor. <b>ЦКП секции — доход от продаж Sales Doctor.</b> Рядом секции IBOX, дополнительных продаж (интеграция и внедрение) и CRM с ЦКП «база клиентов с актуальными данными».</p>
<h4>Поток клиента</h4>
<div class="flow">
<span class="node">4 · Продвижение</span><span class="arr">→</span>
<span class="node">5 · Понимание</span><span class="arr">→</span>
<span class="node me">6 · Продажи</span><span class="arr">→</span>
<span class="node">10 / 11 · Ведение</span><span class="arr">→</span>
<span class="node">12 · Интеграция</span><span class="arr">→</span>
<span class="node">13 · Качество</span>
</div>
<ul>
<li><b>Откуда приходит клиент.</b> Отдел 4 «Продвижение» даёт отклики, отдел 5 «Понимание» — клиента, который понял ценность и хочет купить. Ты не ищешь лид с нуля, ты принимаешь его на входе.</li>
<li><b>Куда уходит после оплаты.</b> В технический департамент: отдел 10 — key account категории A, отдел 11 — категории B и C, отдел 12 — интеграция. Дальше департамент 5 отвечает за качество и обучение клиента.</li>
</ul>
<div class="callout">Схема лежит PDF-файлом у наставника — попроси показать и пройди по ней пальцем: департамент → отдел → секция → ЦКП.</div>$sd$, $sd$[]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000104$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 40, $sd$Рабочее место и ежедневные обязательные задачи$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Что подписывается в первый день?","options":["Договор с клиентом","NDA и документы по HR","Приказ о премии","Ничего"],"correct":1},{"q":"Что изучается в первый день кроме знакомства и доступов?","options":["Скрипты и демо","Оргструктура, основные модули продукта, типовые клиенты A/B/C","Калькулятор ROI","Банк возражений"],"correct":1},{"q":"Сколько времени по регламенту отводится на просмотр задач и планирование дня?","options":["2 минуты","5 минут","20 минут","1 час"],"correct":2},{"q":"Куда записывается идея по улучшению своей работы?","options":["В личные заметки","В журнал «Идеи на внедрение»","В CRM","В WhatsApp РОПу"],"correct":1}]$sd$::jsonb, $sd$<p>Что ставить на компьютер и телефон и как настраивать — в следующем уроке «Инструменты». Здесь — что происходит в первый день и что делает каждый сотрудник каждое утро.</p>
<h4>День 1 по чек-листу адаптации</h4>
<ul>
<li>Знакомство с командой и условиями адаптации</li>
<li>Подписание NDA и документов по HR</li>
<li>Настройка рабочего места: почта, мессенджеры, доступы</li>
<li>Изучение оргструктуры (урок выше)</li>
<li>Знакомство с продуктом: основные модули (день 3)</li>
<li>Типовые клиенты A/B/C (день 3)</li>
</ul>
<h4>Ежедневные обязательные задачи каждого сотрудника</h4>
<p>Общий чек-лист для всех сотрудников компании — не только продаж. Алгоритм рабочего дня менеджера с нормативами — день 2, урок 1.</p>
<ol>
<li>Проверить рабочее место — инструменты и устройства на месте (2 мин)</li>
<li>Включить ПО и устройства (5 мин)</li>
<li>Просмотреть задачи, спланировать бюджет времени (20 мин)</li>
<li>Спросить себя: что улучшить для эффективности? — записать в журнал «Идеи на внедрение»</li>
<li>Найти актуальную новость по своему профилю, выписать значимую</li>
<li>Ознакомиться с журналом идей, обсудить в общем чате (5 мин)</li>
<li>Заполнить экспресс-отчёт по показателям</li>
</ol>$sd$, $sd$[{"t":"Чек-лист ПО и сборник чек-листов","u":"https://docs.google.com/spreadsheets/d/1JJM7ZK5aHcKlfkBXfotGwovXN6V3R75oN4lFQGznkBg/edit"},{"t":"Адаптация · 7 дней (чек-лист)","u":"https://docs.google.com/spreadsheets/d/1yWhWhz5WjgrRNJbmlEEVNYUX-PLW0oZFonoBxceoWq8/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000105$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 50, $sd$Инструменты: amoCRM, Wazzup, АТС Билайн$sd$, $sd$30 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Где ведётся переписка с клиентами в WhatsApp?","options":["В личном WhatsApp","Через Wazzup, привязанный к amoCRM","В Telegram","По email"],"correct":1},{"q":"Что происходит со звонками через АТС Билайн?","options":["Ничего","Записываются и привязываются к сделке в amoCRM","Хранятся только на телефоне","Удаляются через сутки"],"correct":1},{"q":"Основной способ позвонить клиенту:","options":["С личного мобильного","Клик по номеру в карточке amoCRM","Через Wazzup","Через Zoom"],"correct":1},{"q":"Клиент звонит с неизвестного номера. Что делает АТС?","options":["Сбрасывает","Автоматически создаёт контакт и лид","Переводит на РОПа","Ничего"],"correct":1},{"q":"Сколько хранятся записи звонков в кабинете АТС?","options":["Неделю","Месяц","Год","Бессрочно"],"correct":2},{"q":"Зачем Wazzup запрашивает твой личный номер?","options":["Чтобы клиенты звонили на него","Для подтверждения личности, он конфиденциален","Для рассылок","Для отчётов РОПу"],"correct":1}]$sd$::jsonb, $sd$<p>Четыре инструмента, в которых живёт вся работа с клиентом. Всё, что не попало в них, для компании не существует: звонок без записи, переписка в личном WhatsApp и договорённость «на словах» не считаются.</p>
<div class="flow"><span class="node me">amoCRM · сделки и задачи</span><span class="arr">+</span><span class="node">Wazzup · WhatsApp внутри CRM</span><span class="arr">+</span><span class="node">АТС Билайн · звонки и записи</span><span class="arr">+</span><span class="node">Bandicam / dapmeet · встречи</span></div>
<h4>1. amoCRM — центр всего</h4>
<p>Все лиды, контакты, этапы сделок, задачи и примечания. Доступ: отправляешь наставнику ФИО и email, получаешь логин и пароль. Как вести сделки по шагам — <a href="#acad/b0000000-0000-0000-0002-000000000204">день 2, урок 4</a>.</p>
<h4>2. Wazzup — WhatsApp, привязанный к amoCRM</h4>
<ul>
<li><b>Зачем.</b> Все переписки с клиентами ведутся только через Wazzup: сообщения падают в карточку сделки, их видит РОП, они остаются в компании. Личный WhatsApp для клиентов не используется.</li>
<li><b>Условие.</b> Ты должен быть заведён как пользователь amoCRM.</li>
<li><b>Установка.</b> Приложение на смартфон — <a href="https://download-app.wazzup24.com/" target="_blank" rel="noopener">download-app.wazzup24.com</a>; на ПК — <a href="https://web.wazzup24.com/login/" target="_blank" rel="noopener">web.wazzup24.com</a>.</li>
<li><b>Подтверждение.</b> При первом входе приложение запросит номер телефона — указываешь свой личный. Он конфиденциален и нужен только для подтверждения личности.</li>
<li><b>В чате</b> видишь тех клиентов, которые закреплены за тобой в amoCRM.</li>
</ul>
<h4>3. АТС Билайн — все звонки записываются и привязываются к сделке</h4>
<p>Виртуальная АТС Beeline Кыргызстан. Кабинет: <a href="https://zeidplus.ats.beeline.kg/" target="_blank" rel="noopener">zeidplus.ats.beeline.kg</a>. Логин и пароль выдаёт администратор (формат вида <code>имя@компания.ats12345.com</code>).</p>
<table class="tbl"><thead><tr><th>Как звонить</th><th>Что это</th><th>Как войти</th></tr></thead><tbody>
<tr><td><b>Из amoCRM</b> — основной способ</td><td>Кликаешь по номеру в карточке контакта или сделки — АТС набирает. Входящий звонок показывает всплывающую карточку: имя клиента, ответственный, номер, все сделки с ним. Звонок с неизвестного номера автоматически создаёт контакт и лид</td><td>Настраивает администратор в разделе «amoCRM» кабинета АТС</td></tr>
<tr><td><b>Корпоративный мессенджер</b> на ПК</td><td>Софтфон и чаты для Windows / macOS / Linux. Во время звонка — карточка контакта, удержание, перевод, микрофон, выбор исходящего номера. Есть статус «Не беспокоить»</td><td>Логин и пароль из профиля в АТС</td></tr>
<tr><td><b>Мобильное приложение</b> «ВАТС Beeline Кыргызстан»</td><td>iOS и Android. Звонок — круглая кнопка внизу справа в разделах «Сводка», «История», «Статистика». В «Настройки → Управление звонками» задаёшь приём звонков, переадресацию при неответе и в нерабочее время</td><td>Те же логин и пароль, либо QR-код из профиля («Сгенерировать QR-код»)</td></tr>
</tbody></table>
<ul>
<li><b>Записи.</b> Каждый звонок сохраняется в карточке клиента в amoCRM — прослушать можно в любой момент. Полная история — в кабинете АТС, раздел «История и запись звонков»: фильтр по сотруднику и «Время начала звонка», прослушивание и кнопка «Скачать». <b>Записи хранятся год</b> — важное скачивай.</li>
<li><b>Норма.</b> Входящий — трубка до 3-го гудка; пропустил — перезвон в течение 1 часа. Сообщение в Wazzup — ответ за 15 минут. Нет записи разговора — комментарий, скриншот переписки или запись с телефона (чек-лист CRM).</li>
<li><b>База знаний</b> по каждому разделу: <a href="https://wiki.ats.beeline.kg/" target="_blank" rel="noopener">wiki.ats.beeline.kg</a>.</li>
</ul>
<h4>4. Встречи: Google Calendar, Zoom / Meet, Bandicam, dapmeet</h4>
<p>Встреча вносится в Google Calendar, клиенту уходит ссылка Zoom или Google Meet. Демо экрана пишется Bandicam, разговор в Meet транскрибирует dapmeet — подробно в <a href="#acad/b0000000-0000-0000-0002-000000000606">дне 6</a>.</p>
<h4>5. Остальное из чек-листа ПО</h4>
<p>Google Таблицы — Светофор, планёрка, калькулятор ROI. Loom — короткие видео клиенту и внутренние разборы. buildin.ai — база знаний. Почта — письма-резюме после встреч.</p>
<div class="callout">Телефония компании — только АТС Билайн. Никаких других софтфонов и SIP-аккаунтов настраивать не нужно.</div>$sd$, $sd$[{"t":"wazzap · инструкция","u":"https://docs.google.com/document/d/1K0VZKikf9hYNbi9Zk3up260fnN9Omc9fgUwyWTjckzI/edit"},{"t":"Работа с АТС Билайн","u":"https://docs.google.com/document/d/1enMYrHClZ5Fiu88St6y9SWkm4NNZ12OklHPXQins5ek/edit"},{"t":"База знаний АТС · интеграция с amoCRM","u":"https://wiki.ats.beeline.kg/amocrm"},{"t":"База знаний АТС · мобильное приложение","u":"https://wiki.ats.beeline.kg/mobile_app"},{"t":"База знаний АТС · мессенджер для ПК","u":"https://wiki.ats.beeline.kg/messenger"},{"t":"База знаний АТС · история и записи","u":"https://wiki.ats.beeline.kg/history_records"},{"t":"Amo crm · вход","u":"https://docs.google.com/document/d/1BBXU4ZQhZikS7vKvGL5_kZEEdREbgbKqGsUtUNBodGQ/edit"}]$sd$::jsonb, NULL, NULL, true)
