INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000106$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 60, $sd$Регламент коммуникации: стандарты WOW-сервиса$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Как обращаемся к клиенту в переписке?","options":["На ты","На Вы с заглавной буквы, по имени","По фамилии","Как удобно"],"correct":1},{"q":"Клиент задал вопрос вне твоей компетенции. Правильно:","options":["«Это не ко мне, напишите в техподдержку»","Сам подключаешь специалиста и передаёшь ему контекст, называешь срок","Игнорируешь","Отвечаешь наугад"],"correct":1},{"q":"Норма ответа в мессенджере по регламенту коммуникации:","options":["2 часа","15 минут","1 день","5 минут"],"correct":1},{"q":"Не знаешь ответа. Что говоришь?","options":["«Наверное, это работает так…»","«Не знаю, но сейчас узнаю» — и возвращаешься с точным ответом","«Это не мой вопрос»","Молчишь"],"correct":1},{"q":"Клиент недоволен и пишет резко. Первое действие:","options":["Объяснить, что он сам виноват","Признать проблему, поблагодарить за обратную связь, извиниться от лица компании","Передать РОПу без ответа","Дать скидку"],"correct":1}]$sd$::jsonb, $sd$<p>Единый стандарт общения с клиентами для всех сотрудников. По нему считают время первого ответа, выполнение обещаний, CSAT и NPS.</p>
<h4>Шесть универсальных правил</h4>
<table class="tbl"><thead><tr><th>Правило</th><th>Неправильно</th><th>Правильно</th></tr></thead><tbody>
<tr><td><b>На Вы, по имени.</b> Всегда «Вы» с заглавной в письме; на «ты» — только по инициативе клиента</td><td>«Привет, Мирзахит! Ты оставил заявку?»</td><td>«Здравствуйте, Мирзахит! Благодарю за обращение в Sales Doctor Solutions…»</td></tr>
<tr><td><b>Держим слово.</b> Реалистичные сроки с запасом; не успеваем — предупреждаем заранее</td><td>«Пришлю через час» — и не присылает</td><td>«Отправлю Вам сегодня до 17:00. Если потребуется больше времени — сообщу заранее»</td></tr>
<tr><td><b>Не перекладываем ответственность.</b> Фразы «это не ко мне», «обратитесь к другому специалисту» недопустимы</td><td>«Это не ко мне, напишите в техподдержку»</td><td>«Сейчас подключу специалиста и передам ему всё, чтобы Вам не пришлось повторять. Он свяжется в течение часа»</td></tr>
<tr><td><b>Всегда даём обратную связь.</b> Даже «получил, разбираюсь»; о прогрессе — минимум раз в 24 часа</td><td>Молчание несколько часов</td><td>«Получил Ваше сообщение. Проверю и вернусь с ответом в течение 2 часов»</td></tr>
<tr><td><b>Профессиональный тон.</b> Без сленга, жаргона, «как бы / типа»; грамотно</td><td>«Ну это API слетело, респонс не приходит»</td><td>«Произошёл сбой в автоматической передаче данных. Специалисты восстанавливают соединение»</td></tr>
<tr><td><b>Позитивный язык.</b> «Могу предложить» вместо «не могу»; «давайте по-другому» вместо «вы неправильно»</td><td>«Вы неправильно настроили, поэтому не работает»</td><td>«Вижу, что один параметр можно оптимизировать. Сейчас покажу, как»</td></tr>
</tbody></table>
<h4>Скорость реакции</h4>
<ul>
<li>Email / CRM — первый ответ в течение 2 часов в рабочее время</li>
<li>Мессенджеры / чаты — 15 минут</li>
<li>Звонки — трубка до 3-го гудка, callback в течение 1 часа</li>
<li>Критические обращения — немедленно, с эскалацией</li>
<li>Нерабочее время — автоответ с указанием, когда вернёмся</li>
</ul>
<div class="callout"><b>Это единый стандарт времени для всей школы.</b> Те же цифры — в Карте менеджера, регламенте CRM и уроке по инструментам: новый лид — первый контакт в течение 1 часа; входящий звонок — до 3-го гудка, пропущенный — перезвон в течение 1 часа; мессенджеры — 15 минут; email — 2 часа.</div>
<h4>Специфика для менеджеров по продажам</h4>
<ul>
<li>Первый контакт с новым лидом — в течение 1 часа</li>
<li>Персонализируем каждое обращение: откуда пришёл клиент, его индустрия</li>
<li>Сначала вопросы, чтобы понять задачу, — потом продукт</li>
<li>Действующим клиентам — плановое касание раз в месяц, не только когда есть что продать</li>
<li>Информируем о новых возможностях, релевантных клиенту; не навязываем</li>
</ul>
<h4>Сложные ситуации</h4>
<ul>
<li><b>Клиент недоволен:</b> не спорим, благодарим за обратную связь, извиняемся от лица компании, быстро предлагаем решение, эскалируем, если не можем сами.</li>
<li><b>Не знаем ответа:</b> «Не знаю, но сейчас узнаю» — и точный ответ через 30 минут. Не выдумываем, не «наверное».</li>
<li><b>Допустили ошибку:</b> признаём сразу, извиняемся, план исправления, делаем больше, чем ожидалось.</li>
<li><b>Нужно сказать «нет»:</b> причина + альтернатива, вежливо.</li>
</ul>
<h4>Самопроверка перед отправкой</h4>
<ul class="check"><li>На Вы?</li><li>Без ошибок?</li><li>Тон уважительный?</li><li>Ответил на вопрос?</li><li>Понятно, что дальше и когда?</li><li>Не перекладываю ответственность?</li></ul>
<p>Метрики: время первого ответа, выполнение обещаний в срок, CSAT &gt; 4,5 / 5, NPS &gt; 70, число эскалаций.</p>$sd$, $sd$[{"t":"Регламент коммуникации с клиентами","u":"https://docs.google.com/document/d/1RVni5tsiYR57PfE2gE-d1PkXCO-b_Vno6Pq6gn5j4t4/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000107$sd$, $sd$a0000000-0000-0000-0002-000000000001$sd$, 70, $sd$ТОП-10 ошибок новичков$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Ошибка №1 новичка по документу:","options":["Слишком много звонит","Не изучает продукт","Слишком вежлив","Работает по выходным"],"correct":1},{"q":"Сколько отказов получают даже топовые менеджеры?","options":["10–20 %","30–40 %","70–80 %","0 %"],"correct":2},{"q":"Возражение «дорого» — это…","options":["Окончательный отказ","Запрос на дополнительную информацию","Сигнал дать скидку","Повод закрыть сделку"],"correct":1},{"q":"Сколько сделок умирают без follow-up?","options":["10 %","30 %","50 %","80 %"],"correct":3},{"q":"Сколько времени на изучение клиента перед каждой встречей?","options":["0","5 минут","20 минут","2 часа"],"correct":2}]$sd$::jsonb, $sd$<p>Каждая из этих ошибок стоила компании сделок. Знаешь о них заранее — пропускаешь 90 % типичных провалов.</p>
<ol class="rules">
<li><b>Не изучают продукт.</b> Не можешь ответить на технический вопрос — теряешь доверие. → Первая неделя: изучи продукт как пользователь, составь 20 вопросов клиента и выучи ответы.</li>
<li><b>Не изучают бизнес клиента.</b> Показываешь стандартную презентацию — клиент думает «ему всё равно». → 20 минут перед каждой встречей: сайт, ассортимент, соцсети, 3–5 вопросов про процессы.</li>
<li><b>Думают, что продажи зависят только от лидов.</b> → Лучшие генерируют сделки сами: список из 50 компаний, 10 холодных касаний в день, база «не купили полгода назад», рефералы.</li>
<li><b>Не пользуются инструментами.</b> Блокнот вместо CRM → забыл перезвонить → клиент купил у конкурента. → Всё в CRM, напоминания на все даты, раз в неделю смотри воронку.</li>
<li><b>Видят в клиенте деньги, а не помощь.</b> Клиент чувствует фальшь. → «Купил бы я это сам для своего бизнеса?» Не подходит — скажи честно.</li>
<li><b>Боятся отказов.</b> Даже топы получают 70–80 % отказов. → Веди статистику: 10 звонков → 3 встречи → 1 сделка. Спрашивай причину отказа. Празднуй активность.</li>
<li><b>Сразу презентуют, не задавая вопросов.</b> → 70/30: первые 15 минут — только вопросы. Презентуй решение боли, а не весь продукт.</li>
<li><b>Сдаются после первого «дорого».</b> Возражение ≠ отказ, это запрос информации. → «С чем сравниваете? Давайте посчитаем окупаемость». «Над чем конкретно хотите подумать?»</li>
<li><b>Не следят за сделкой после встречи.</b> 80 % сделок умирают без follow-up. → После каждой встречи — следующий шаг с датой. 3–5 касаний — норма, не навязчивость.</li>
<li><b>Не просят обратную связь.</b> → Раз в неделю слушай свои звонки, разбирай проваленные сделки, проси РОПа послушать звонок, веди дневник обучения.</li>
</ol>
<div class="callout"><b>Что сделать сейчас:</b> выбери 3 ошибки, которые допускаешь чаще всего, и внедряй по одному решению в неделю. Через месяц вернись к списку.</div>$sd$, $sd$[{"t":"ТОП-10 ошибок новичков","u":"https://docs.google.com/document/d/19WKExiSBUIn48oOH4VPUb0ycwZlqgnWwO-2Y1Z-BMHc/edit"}]$sd$::jsonb, NULL, NULL, true)
